import React from 'react';

const Model = ({ isOpen, onClose, children }) => {
  if (!isOpen) return null; // لا تظهر شيئاً إذا كانت الحالة مغلقة

  return (
    <div style={{
      position: 'fixed', top: 0, left: 0, width: '100%', height: '100%',
      backgroundColor: 'rgba(0, 0, 0, 0.5)', display: 'flex',
      justifyContent: 'center', alignItems: 'center', zIndex: 1000
    }} onClick={onClose}>
      <div style={{
        backgroundColor: 'white', padding: '30px', borderRadius: '15px',
        maxWidth: '800px', width: '90%', maxHeight: '90vh', overflowY: 'auto',
        position: 'relative'
      }} onClick={e => e.stopPropagation()}> {/* منع إغلاق المودال عند الضغط داخله */}
        <button onClick={onClose} style={{ position: 'absolute', top: '15px', right: '15px', border: 'none', background: 'none', fontSize: '20px', cursor: 'pointer' }}>
          ✕
        </button>
        {children}
      </div>
    </div>
  );
};

export default Model;
